/bin/bash -lc "python - <<'PY'
from ansible.utils.encrypt import passlib_or_crypt
for ident in ('2','2a','2y','2b'):
 try:
  print(ident,passlib_or_crypt('secret','bcrypt',salt='123456789012345678901u',rounds=4,ident=ident)[:7])
 except Exception as e: print(ident,type(e).__name__,str(e)[:100])
PY"

